template:
fn indexed_labels(items: &[&str]) -> Vec<String> {
    items
        ⟦iter_source⟧
        .map(⟦closure_arg⟧)
        .collect()
}

fn main() {
    let labels = indexed_labels(&["apple", "banana"]);
    println!("{labels:?}");
}

tests:
#[test]
fn formats_with_indices() {
    assert_eq!(indexed_labels(&["apple", "banana"]), vec!["0: apple", "1: banana"]);
}
